export default class Selectable<T> {
	public item : T;

	constructor() {
		this.item = null;
	}

	get selected(){
		return this.item;
	}

	set selected(val : T){
		this.item = val;
	}

	isSelected(val : T) {
		return this.item === val;
	}

	select(val : T) {
		if (val === this.item) {
			this.item = null;
		} else {
			this.item = val;
		}
	}

	dropSelect() {
		this.item = null;
	}
}


