const module = angular.module("irtech.netcity.em.educcertificates",
	[
		"ngRoute", "ngSanitize", "ngMessages", "ui.select", "uikit.alerts", "uikit.dialogs", "ui.bootstrap", "ngFileUpload", "ui.tree",
		"irtech.netcity.common", "irtech.netcity.ui-components"
	]);

require("./registry/educCertifsRegistryCtrl.js");
require("./edit/editEducCertifCtrl.js");
require("./edit/searchEducCertifCtrl.js"); 

const registryTemplate = "/static/dist/app/global/templates/registry.html";

import { EducCertifRepository } from "approot/school/educcertificates/common/repository.js";

import { SearchStudentService } from "approot/em/educcertificates/edit/searchStudentCtrl.js";

module
	.factory("certifRepository", ($http, $dialogs, $alerts) => new EducCertifRepository($http, $dialogs, $alerts))
	.factory("searchStudentService", ($uibModal) => new SearchStudentService($uibModal))
	.directive("nsDateModel", () => {
		const toStr = function (dateParam) {
			return dateParam ? dateUtils.date2str(new Date(dateParam)) : null;
		}
		return {
			restrict: 'A',
			scope: {
				date: "=nsDateModel"
			},
			link: (scope, element) => {
				let isoDate = scope.date;
				let strDate = toStr(isoDate);

				$(element).val(strDate);

				$(element).change(() => {
					let date = dateUtils.str2date($(element).val());
					if (date) {
						scope.date = date.toISOString();
					} else {
						scope.date = null;
					}
					scope.$apply();
				});
			},
			replace: false
		}
	})
	.config(($routeProvider, $locationProvider) => {
		$routeProvider
			.when("/registry/", {
				templateUrl: registryTemplate,
				controller: "EducCertifsRegistryCtrl"
			})
			.otherwise({
				templateUrl: registryTemplate,
				controller: "EducCertifsRegistryCtrl"
			});
		$locationProvider.hashPrefix('');
		$locationProvider.html5Mode({
			enabled: true,
			requireBase: true
		});
	});


