"use strict";



angular
	.module("irtech.netcity.em.educcertificates")
	.controller("SearchEducCertifCtrl", ($scope, $http, $document, $location, $appLoader, $uibModal, $uibModalInstance, $alerts, $q, $dialogs, certifRepository) => {

		$scope.certifNumber = undefined;
		$scope.lastname = undefined;
		$scope.firstname = undefined;
		$scope.middlename = undefined;
		$scope.noMiddlename = undefined;
		$scope.isSearchComplete = undefined;
		$scope.isCertifNotFinded = true;

		$scope.isValidForm = () => {

			let isFioFill = $scope.lastname && $scope.firstname && true;
			let isCertNumberFill = $scope.certifNumber && true;

			let res = isFioFill || isCertNumberFill;

			return res;
		}

		$.extend($scope,
			{
				language: language,
			}
		);

		$scope.search = () => {
			$scope.isSearchCompleted = false;
			$scope.isCertifNotFinded = true;

			let searchData = {
				ceretNumber: $scope.certifNumber || '',
				lastname: $scope.lastname || '',
				firstname: $scope.firstname || '',
				middlename: $scope.middlename || '',
				noMiddlename: $scope.noMiddlename || false,
			}

			let searchCertificatePromise = certifRepository.searchCertificate(searchData);
			let getChildEmWithMainPromise = certifRepository.getChildEmWithMain();


			Promise.all([searchCertificatePromise, getChildEmWithMainPromise]).then(data => {

				let findedCertificates = data[0];
				let childEmsWithMain = data[1];

				//првоерить что текущий муниципалитет сертификата есть в списке из доступных муниципалитетов, если его там нет, то добавить
				for (let i = 0; i < findedCertificates.length; i++) {
					let cert = findedCertificates[i];
					cert.municipalitetList = childEmsWithMain;

					let isCurrentMunicipalitetInList = cert.municipalitetList.some(x => x.id == cert.currentMunicipalitet.id);

					if (!isCurrentMunicipalitetInList) {
						cert.municipalitetList.push(cert.currentMunicipalitet);
					}
				}

				$scope.isSearchCompleted = true;

				if (findedCertificates.length < 1) {
					$scope.isCertifNotFinded = true;
				} else {
					$scope.isCertifNotFinded = false;
					$scope.findCertifStudList = findedCertificates;
					$scope.municipalitetList = childEmsWithMain;
				}

				//вручную запускаю дайджест цикл
				$scope.$digest();
			});
		}


		$scope.cancel = () => {
			return $uibModalInstance.dismiss("cancel");
		};

		$scope.save = () => {

			let data = $scope.findCertifStudList;

			certifRepository.updateMunicipalitetForCertif(data)
				.then((response) => {
					return $uibModalInstance.dismiss("cancel");
				}).then(() => {
					$alerts.success("Сертификат успешно сохранен");
				});
		};

	});



