"use strict";

require("approot/global/controllers/registryCtrl.js");
import { PfdoIntegrationType } from "approot/global/settingsProvider";

angular
	.module("irtech.netcity.em.educcertificates")
	.controller("EducCertifsRegistryCtrl", ($scope, $controller, $http, $document, $location, $appLoader, $uibModal, $alerts, certifRepository, searchStudentService, settingsProvider, downloadService, $q) => {

		$scope.$parent.page = {
			title: "Сертификаты дополнительного образования"
		};

		const dateDecorator = { type: "map", map: (date) => dateUtils.date2str(new Date(date)) };

		$scope.edit = (certif) => {

			certifRepository.get(certif.id)
				.then((certifInfo) => {
					var modalInstance = $uibModal.open({
						templateUrl: "/static/dist/app/school/educcertificates/common/editEducCertificateTemplate.html",
						controller: 'EditCertifCtrl as editCtrl',
						resolve: {
							certifInfo: () => certifInfo,
							searchCtx: () => null
						}
					});

					modalInstance.rendered.then(() => {
						dateInput.initDateInputs(null, null, null, { format: dateUtils.getDateFormat().format });
					});

					modalInstance.result.then(() => {
						$scope.load();
					});

				});

		};

		$scope.fieldDecorators = {
			"studentBirthDate": dateDecorator,
			"startDate": dateDecorator,
			"endDate": dateDecorator,
			"number": { type: "link", action: $scope.edit },
			"identityDocumentInfo": { type: "preserveWhiteSpace" },
			"parentsInfo": { type: "preserveWhiteSpace" },
			"addressInfo": { type: "preserveWhiteSpace" }
		};

		$scope.linkButtons = [];

		const addCertifButton = {
			title: language.Generic.Buttons.kAdd,
			icon: "glyphicon glyphicon-plus-sign",
			action: () => {
				$scope.add();
			}
		};

		//кнопка поиск сертификатов
		const searchCertifButton = {
			title: 'Поиск сертификата',
			icon: "glyphicon glyphicon-search",
			action: () => {

				var modalInstance = $uibModal.open({
					templateUrl: "/static/dist/app/em/educcertificates/edit/searchEducCertifs.html",
					controller: 'SearchEducCertifCtrl as searchCtrl',
					size: "lg"
				});
			}
		};

		$scope.add = () => {
			searchStudentService.search().then((student) => {
				const certifInfo = {
					studentId: student.id,
					studentFio: student.studentFio,
					number: null,
					startDate: moment(new Date()).toDate(),
					endDate: moment(student.studentBirthDate).add(18, "years").startOf("day").toDate(),
					status: "Actual",
					studentBirthDate: student.studentBirthDate
				};

				var modalInstance = $uibModal.open({
					templateUrl: "/static/dist/app/school/educcertificates/common/editEducCertificateTemplate.html",
					controller: 'EditCertifCtrl as editCtrl',
					resolve: {
						certifInfo: () => certifInfo,
						searchCtx: () => null
					}
				});

				modalInstance.rendered.then(() => {
					dateInput.initDateInputs(null, null, null, { format: dateUtils.getDateFormat().format });
				});

				modalInstance.result.then(() => {
					$scope.load();
				});

			});
		}

		const getPfdoType = settingsProvider.ServerSettings.SystemSettings.IntegrationPFDOType().then((pfdoType) => {
			if (pfdoType == PfdoIntegrationType.Volgograd) { 
				$scope.linkButtons.push({
					title: "Шаблон заявления",
					action: () => downloadService.downloadFile("/files/Шаблон Заявления.pdf", { filename: "Шаблон Заявления.pdf" })
				});
			}
		});

		const getEditCertificatesDOOnlyByRegion = settingsProvider.ServerSettings.SystemSettings.EditCertificatesDOOnlyByRegion().then((onlyByRegion) => {
			if (onlyByRegion && !appContext.isTopEm) { // cantEditCertif
				$scope.fieldDecorators["number"] = null;
			}
		});

		$q.all([getPfdoType, getEditCertificatesDOOnlyByRegion]).then(() => {
			$scope.registry = {
				url: "/webapi/em/educcertificates/registry",
				filtersUrl: "/webapi/em/educcertificates/registry/filter",
				fieldDecorators: $scope.fieldDecorators,
				buttons: [],
				linkButtons: $scope.linkButtons
			};
			$scope.registry.buttons.push(searchCertifButton);

			if (appContext.hlevel !== 1) {
				//УО смешенного уровня - не должно иметь прав на создание
				$scope.registry.buttons.push(addCertifButton);
			}
			$controller("RegistryCommonCtrl", { $scope, $http, $document, $location, $appLoader, $uibModal, $alerts, settingsProvider });
		});

	});



