import * as ServerSettingsInfo from "approot/global/references/serverSettings.js";
import { UploadLimits } from "./models/common.model";

class SystemSettings {
	constructor(private $http: any) {
	}

	private getSetting<T>(id: number): Promise<T> {
		return this.$http.get("/webapi/settings", { params: { id: id } })
			.then((response) => <T>response.data);
	}

	private getSettingByKey<T>(key: string): Promise<T> {
		return this.$http.get("/webapi/settings/" + key)
			.then((response) => <T>response.data);
	}

	private getBoolSetting(id: number): Promise<boolean> {
		return this.$http.get("/webapi/settings", { params: { id: id } })
			.then((response) => response.data == "1");
	}

	IsRegionEMForSchool(): Promise<boolean> {
		return this.getBoolSetting(ServerSettingsInfo.IsRegionEMForSchool);
	}

	LaIntegrationCourses(): Promise<boolean> {
		return this.getBoolSetting(ServerSettingsInfo.LaIntegrationCourses);
	}

	ModuleQA(): Promise<boolean> {
		return this.$http.get("/webapi/settings/ModuleQA")
			.then((response) => response.data);
	}

	MinLoginLength(): Promise<number> {
		//todo. настройка на сервере появилась в рамках #24256
		return Promise.resolve(5);
		//return this.getSettingByKey("minLoginLength");
	}

	IntegrationPFDOType(): Promise<PfdoIntegrationType> {
		return this.$http.get("/webapi/settings/IntegrationPFDOType")
			.then((response) => response.data);
	}

	EditCertificatesDOOnlyByRegion(): Promise<boolean> {
		return this.getBoolSetting(ServerSettingsInfo.EditCertificatesDOOnlyByRegion);
	}
}

class UserAuthorizationSettings {
	constructor(private $http: any) {
	}

	WindowsAuth(): Promise<boolean> {
		return this.$http.get("/webapi/settings/windowsAuth")
			.then((response) => response.data);
	}
}

class ServerSettings {
	public SystemSettings: SystemSettings;
	public UserAuthorizationSettings: UserAuthorizationSettings;

	constructor($http: ng.IHttpService) {
		this.SystemSettings = new SystemSettings($http);
		this.UserAuthorizationSettings = new UserAuthorizationSettings($http);
	}
}

class LocalSettings {
	constructor(private $http: any) {
	}

	private getSetting<T>(id: number): Promise<T> {
		return this.$http.get("/webapi/settings", { params: { id: id } })
			.then((response) => <T>response.data);
	}

	private getSettingByKey<T>(key: string): Promise<T> {
		return this.$http.get("/webapi/settings/" + key)
			.then((response) => <T>response.data);
	}

	RegExpAlphabet(): Promise<string> {
		return this.getSettingByKey("regExpAlphabet");
	}

	FirstLetter(): Promise<string> {
		return this.getSettingByKey("firstLetter");
	}

	LastLetter(): Promise<string> {
		return this.getSettingByKey("lastLetter");
	}

	PhoneStateCode(): Promise<string> {
		return this.getSettingByKey("phoneStateCode");
	}

	PhoneNumberLength(): Promise<number> {
		return this.getSettingByKey("phoneNumberLength");
	}
	PhoneTemplate(): Promise<string> {
		return this.getSettingByKey("phoneTemplate");
	}
}

class AppFlags {
	constructor(private $http) {
	}

	PersonData() {
		return this.$http.get("/webapi/appflags/persondata")
			.then((response) => response.data);
	}
}

export class SettingsProvider {
	public ServerSettings: ServerSettings;
	public LocalSettings: LocalSettings;
	public AppFlags: AppFlags;

	public get UploadLimits(): Promise<UploadLimits> {
		return <Promise<UploadLimits>>this.$http.get("/webapi/attachments/uploadLimits")
			.then((response) => {
				return <UploadLimits>response.data;
			});
	};

	/*@ngInject*/
	constructor(private $http: ng.IHttpService) {
		this.ServerSettings = new ServerSettings($http);
		this.LocalSettings = new LocalSettings($http);
		this.AppFlags = new AppFlags($http);
	}
}

export enum PfdoIntegrationType {
	/// <summary>
	/// Самарский ПФДО ИРТех
	/// </summary>
	IRTechEes = "IRTechEes",
	/// <summary>
	/// Челябинский образовательный портал - Навигатор доп. образования
	/// </summary>
	IRTech = "IRTech",
	/// <summary>
	/// Волгоградский ПФДО 
	/// </summary>
	Volgograd = "Volgograd",
}


