import Selectable from "approot/global/selectable";

class SeachStudentController {
	constructor($uibModalInstance, $http) {
		this.$http = $http;
		this.language = language;
		this.$uibModalInstance = $uibModalInstance;
		this.title = "Поиск учащегося";
		this.students = [];
		this.searchCompleted = false;
		this.searchData = {
			lastname: "",
			firstname: "",
			middlename: ""
		};
		this.selection = new Selectable();
	}

	search() {
		this.$http.get("/webapi/educcertificates/searchstudent", {params: this.searchData}).then((response) => {
			this.selection.dropSelect();
			this.searchCompleted = true;
			this.students = response.data;

			if (this.students.length === 1) {
				this.selection.select(this.students[0]);
			}
		});
	}

	select() {
		this.$uibModalInstance.close(this.selection.selected);
	}

	cancel() {
		this.$uibModalInstance.dismiss("cancel");
	}
}


class SearchStudentService {

	constructor($uibModal) {
		this.$uibModal = $uibModal;
	}

	search() {
		var modalInstance = this.$uibModal.open({
			templateUrl: "/static/dist/app/em/educcertificates/edit/searchStudent.html",
			controller: SeachStudentController,
			controllerAs: "searchCtrl",
			size: "lg",
			resolve: {}
		});

		return modalInstance.result.then((student) => {
			return student;
		});
	}
}

module.exports = { SeachStudentController, SearchStudentService };


